let data=structuredClone(fallback);
function readSavedLanguage(){
  const q=new URLSearchParams(location.search).get('lang');
  if(q==='en'||q==='ar')return q;
  try{
    const saved=localStorage.getItem('alsiteen_lang')||sessionStorage.getItem('alsiteen_lang');
    if(saved==='en'||saved==='ar')return saved;
  }catch(_){}
  const htmlLang=(document.documentElement.lang||'').toLowerCase();
  return htmlLang==='en'?'en':'ar';
}
function persistLanguage(value){
  try{localStorage.setItem('alsiteen_lang',value);sessionStorage.setItem('alsiteen_lang',value)}catch(_){}
}
let lang=readSavedLanguage();
persistLanguage(lang);
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function normalizePayload(j){if(!j||typeof j!=="object")return null;if(j.data&&typeof j.data==="object")j=j.data;const out={...structuredClone(fallback),settings:{...fallback.settings,...(j.settings||{})}};
  const cleanList=(key,valid)=>{
    if(!Array.isArray(j[key]))return;
    const cleaned=j[key].filter(x=>x&&typeof x==='object'&&valid(x));
    // لا نستبدل بيانات الموقع الأساسية بصفوف فارغة/تالفة قادمة من الشيت.
    if(cleaned.length)out[key]=cleaned;
  };
  cleanList('stats',x=>String(x.labelAr||x.labelEn||'').trim()||Number(x.value));
  cleanList('socials',x=>String(x.name||x.url||'').trim());
  cleanList('services',x=>String(x.ar||x.en||'').trim());
  cleanList('doctors',x=>String(x.nameAr||x.nameEn||'').trim());
  cleanList('insurers',x=>String(x.ar||x.en||x.image||'').trim());
  cleanList('suppliers',x=>String(x.ar||x.en||x.image||'').trim());
  /* Offers are authoritative from the admin/Excel source. An empty array means deliberately empty and must never fall back to bundled demo data. */
  if(Array.isArray(j.offers))out.offers=j.offers.filter(x=>x&&typeof x==='object');
  if(Array.isArray(out.stats)){out.stats=out.stats.map(x=>{const ar=String(x.labelAr||''),en=String(x.labelEn||'');if((Number(x.value)===24||ar.includes('24 تخصص')||en.includes('24 specialties'))&&String(x.icon||'').includes('✚'))return {...x,value:11,labelAr:'أكثر من 11 تخصص',labelEn:'More than 11 specialties'};return x})}return out}
function pageKind(){return document.querySelector('#offersGrid')?'offers':document.querySelector('#doctorsGrid')?'doctors':'home'}
function pageCacheKey(){return 'alsiteen_page_cache_v5_'+pageKind()}
function readCachedData(){
  try{
    const raw=localStorage.getItem(pageCacheKey())||localStorage.getItem('alsiteen_content_cache_v4');
    if(!raw)return null;
    const parsed=JSON.parse(raw);
    return normalizePayload(parsed?.payload||parsed);
  }catch(e){return null}
}
function writeCachedData(payload,version){
  try{localStorage.setItem(pageCacheKey(),JSON.stringify({savedAt:Date.now(),version:version||'',payload}));if(version)localStorage.setItem('alsiteen_content_version',String(version))}catch(e){}
}
async function fetchJsonAction(action,timeout=3600){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);
  try{const u=CONFIG.sheetApiUrl+(CONFIG.sheetApiUrl.includes('?')?'&':'?')+'action='+encodeURIComponent(action)+'&_='+Date.now();const r=await fetch(u,{cache:'no-store',signal:controller.signal});if(!r.ok)throw new Error('HTTP '+r.status);return await r.json()}finally{clearTimeout(timer)}
}
function pageAction(){return pageKind()==='offers'?'getOffers':pageKind()==='doctors'?'getDoctorsPage':'getHome'}
async function refreshRemoteData(force=false){
  try{
    let version='';
    try{const vr=await fetchJsonAction('getVersion',1800);version=String(vr?.version||vr?.data?.version||'')}catch(_){/* old deployment */}
    const localVersion=String(localStorage.getItem('alsiteen_content_version')||'');
    const hasCache=!!localStorage.getItem(pageCacheKey());
    if(!force&&version&&localVersion===version&&hasCache){sessionStorage.setItem('alsiteen_last_bg_sync',String(Date.now()));return}
    const raw=await fetchJsonAction(pageAction(),pageKind()==='offers'?5200:3600);
    const n=normalizePayload(raw);
    if(n){const before=JSON.stringify(data),after=JSON.stringify(n);writeCachedData(raw,version);if(Array.isArray(n.doctors))writeDoctorsFastCache(n.doctors);sessionStorage.setItem('alsiteen_last_bg_sync',String(Date.now()));if(before!==after){data=n;render()}}
  }catch(e){console.warn('Background content refresh skipped:',e)}
}
function readDoctorsFastCache(withMeta=false){
  try{
    const raw=localStorage.getItem('alsiteen_doctors_fast_v2')||localStorage.getItem('alsiteen_doctors_fast_v1');
    if(!raw)return withMeta?null:null;
    const parsed=JSON.parse(raw), doctors=Array.isArray(parsed?.doctors)?parsed.doctors:null;
    if(!doctors)return null;
    return withMeta?{doctors,savedAt:Number(parsed?.savedAt||0)}:doctors;
  }catch(e){return null}
}
function writeDoctorsFastCache(doctors){
  try{if(Array.isArray(doctors))localStorage.setItem('alsiteen_doctors_fast_v2',JSON.stringify({savedAt:Date.now(),doctors}))}catch(e){}
}
function doctorSkeletons(){
  return `<div class="doctors-skeleton-row">${Array.from({length:3},()=>`<article class="doctor-card doctor-skeleton-card"><div class="doctor-skeleton-photo skeleton-shimmer"></div><div class="doctor-info"><i class="skeleton-line w35"></i><i class="skeleton-line w70"></i><i class="skeleton-line w50"></i><i class="skeleton-line w100"></i><i class="skeleton-line w100"></i><i class="skeleton-button"></i></div></article>`).join('')}</div>`;
}
async function prefetchDoctorsInBackground(force=false){
  if(document.querySelector('#doctorsGrid'))return;
  const meta=readDoctorsFastCache(true);
  if(!force&&meta?.doctors?.length&&Date.now()-meta.savedAt<30*60*1000)return;
  try{
    const raw=await fetchJsonAction('getDoctorsPage',4800);
    const list=raw?.data?.doctors||raw?.doctors;
    if(Array.isArray(list))writeDoctorsFastCache(list);
  }catch(e){console.warn('Doctors prefetch skipped:',e)}
}
async function refreshDoctorsFast(){
  if(!document.querySelector('#doctorsGrid'))return;
  try{
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),2800);
    const u=CONFIG.sheetApiUrl+(CONFIG.sheetApiUrl.includes('?')?'&':'?')+'action=getDoctorsPage&_='+Date.now();
    const r=await fetch(u,{cache:'no-store',signal:controller.signal});clearTimeout(timer);
    if(!r.ok)throw new Error('HTTP '+r.status);
    const raw=await r.json();
    const list=raw?.data?.doctors||raw?.doctors, n=normalizePayload(raw);
    if(n){
      if(Array.isArray(list))writeDoctorsFastCache(list);
      writeCachedData(raw,raw?.version||'');
      sessionStorage.setItem('alsiteen_last_bg_sync',String(Date.now()));
      data=n;render();
    }
  }catch(e){console.warn('Fast doctors refresh skipped:',e)}
}
function loadData(){
  // Paint instantly. On the doctors page, restore the small doctors-only cache first,
  // then refresh doctors independently without waiting for the much larger getAll payload.
  const doctorsPage=!!document.querySelector('#doctorsGrid');
  const fastDoctors=doctorsPage?readDoctorsFastCache():null;
  if(fastDoctors?.length)data={...data,doctors:fastDoctors};
  render();
  if(doctorsPage&&!fastDoctors?.length){
    const host=document.querySelector('#doctorsGrid');
    if(host)host.innerHTML=doctorSkeletons();
    document.querySelector('#doctorsEmpty')?.classList.add('hidden');
  }
  const cached=readCachedData();
  if(cached){
    if(doctorsPage&&fastDoctors?.length)cached.doctors=fastDoctors;
    data=cached;render();
  }
  if(doctorsPage)refreshDoctorsFast();
  else {
    const prefetch=()=>prefetchDoctorsInBackground(false);
    if('requestIdleCallback' in window)requestIdleCallback(prefetch,{timeout:2200});
    else setTimeout(prefetch,900);
  }
  const startRefresh=()=>{
    const last=Number(sessionStorage.getItem('alsiteen_last_bg_sync')||0);
    if(Date.now()-last<300000)return; // فحص خفيف كل 5 دقائق فقط؛ تغييرات المحتوى تُكتشف عبر رقم الإصدار.
    refreshRemoteData();
  };
  // كل ما يأتي من Google Sheets صار stale-while-revalidate: الصفحة ترسم من الكاش فورًا والتحديث يتم بعد ذلك في الخلفية.
  const delay=doctorsPage?2200:1200;
  if('requestIdleCallback' in window)requestIdleCallback(()=>setTimeout(startRefresh,delay),{timeout:doctorsPage?3500:2500});
  else if(document.readyState==='complete')setTimeout(startRefresh,delay);
  else window.addEventListener('load',()=>setTimeout(startRefresh,delay),{once:true});
}
function esc(s=''){return String(s).replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}function val(ar,en){return lang==='ar'?ar:en}function cleanPhone(v){return String(v||'').replace(/\D/g,'')}
